INSERT INTO _m100_assert SELECT IF(COUNT(*)=0,1,0) FROM _m100_stats n JOIN merc_stats s USING(merc_npc_type_id,clientlevel) WHERE NOT (s.`merc_npc_type_id` <=> n.`merc_npc_type_id` AND s.`clientlevel` <=> n.`clientlevel` AND s.`level` <=> n.`level` AND s.`hp` <=> n.`hp` AND s.`mana` <=> n.`mana` AND s.`AC` <=> n.`AC` AND s.`ATK` <=> n.`ATK` AND s.`STR` <=> n.`STR` AND s.`STA` <=> n.`STA` AND s.`DEX` <=> n.`DEX` AND s.`AGI` <=> n.`AGI` AND s.`_INT` <=> n.`_INT` AND s.`WIS` <=> n.`WIS` AND s.`CHA` <=> n.`CHA` AND s.`MR` <=> n.`MR` AND s.`CR` <=> n.`CR` AND s.`DR` <=> n.`DR` AND s.`FR` <=> n.`FR` AND s.`PR` <=> n.`PR` AND s.`Corrup` <=> n.`Corrup` AND s.`mindmg` <=> n.`mindmg` AND s.`maxdmg` <=> n.`maxdmg` AND s.`attack_count` <=> n.`attack_count` AND s.`attack_speed` <=> n.`attack_speed` AND s.`attack_delay` <=> n.`attack_delay` AND s.`special_abilities` <=> n.`special_abilities` AND s.`Accuracy` <=> n.`Accuracy` AND s.`hp_regen_rate` <=> n.`hp_regen_rate` AND s.`mana_regen_rate` <=> n.`mana_regen_rate` AND s.`runspeed` <=> n.`runspeed` AND s.`statscale` <=> n.`statscale` AND s.`spellscale` <=> n.`spellscale` AND s.`healscale` <=> n.`healscale`);
INSERT INTO merc_stats(`merc_npc_type_id`,`clientlevel`,`level`,`hp`,`mana`,`AC`,`ATK`,`STR`,`STA`,`DEX`,`AGI`,`_INT`,`WIS`,`CHA`,`MR`,`CR`,`DR`,`FR`,`PR`,`Corrup`,`mindmg`,`maxdmg`,`attack_count`,`attack_speed`,`attack_delay`,`special_abilities`,`Accuracy`,`hp_regen_rate`,`mana_regen_rate`,`runspeed`,`statscale`,`spellscale`,`healscale`) SELECT n.`merc_npc_type_id`,n.`clientlevel`,n.`level`,n.`hp`,n.`mana`,n.`AC`,n.`ATK`,n.`STR`,n.`STA`,n.`DEX`,n.`AGI`,n.`_INT`,n.`WIS`,n.`CHA`,n.`MR`,n.`CR`,n.`DR`,n.`FR`,n.`PR`,n.`Corrup`,n.`mindmg`,n.`maxdmg`,n.`attack_count`,n.`attack_speed`,n.`attack_delay`,n.`special_abilities`,n.`Accuracy`,n.`hp_regen_rate`,n.`mana_regen_rate`,n.`runspeed`,n.`statscale`,n.`spellscale`,n.`healscale` FROM _m100_stats n WHERE NOT EXISTS(SELECT 1 FROM merc_stats s WHERE s.merc_npc_type_id=n.merc_npc_type_id AND s.clientlevel=n.clientlevel);
